//! Cargo-driven `libxslt.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The module is C, compiled and linked by reactos-link: there is no Rust body.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x72ba0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7fefa000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7fefa000000u64)),
        o => panic!("libxslt-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["engine:c:libxml2", "engine:c:iconv-static", "engine:c:zlib", "import:msvcrt", "import:ws2_32", "import:bcrypt", "import:kernel32", "engine:oldnames", "body", "import:ntdll"],
        "x86_64" => &["engine:c:libxml2", "engine:c:iconv-static", "engine:c:zlib", "import:msvcrt", "import:ws2_32", "import:bcrypt", "import:kernel32", "engine:oldnames", "body", "import:ntdll"],
        "aarch64" => &["engine:c:libxml2", "engine:c:iconv-static", "engine:c:zlib", "import:msvcrt", "import:ws2_32", "import:bcrypt", "import:kernel32", "engine:oldnames", "body", "import:ntdll"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .c_from_compile_db("libxslt_shims", &["vendor/libxslt/attributes.c", "vendor/libxslt/attrvt.c", "vendor/libxslt/documents.c", "vendor/libxslt/extensions.c", "vendor/libxslt/extra.c", "vendor/libxslt/functions.c", "vendor/libxslt/imports.c", "vendor/libxslt/keys.c", "vendor/libxslt/namespaces.c", "vendor/libxslt/numbers.c", "vendor/libxslt/pattern.c", "vendor/libxslt/preproc.c", "vendor/libxslt/security.c", "vendor/libxslt/templates.c", "vendor/libxslt/transform.c", "vendor/libxslt/variables.c", "vendor/libxslt/xslt.c", "vendor/libxslt/xsltlocale.c", "vendor/libxslt/xsltutils.c"])
        .whole_c_objects("libxslt_shims")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/bcrypt/bcrypt.spec", "bcrypt.dll", "bcrypt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        // No code of its own: link nothing from rustc's bin (its panic
        // handler, i386's rsbegin/rsend), so the PE is cmake's.
        .shell_less()
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
